def trap(height):
if not height: return 0
l, r = 0, len(height)-1
left_max = right_max = 0
water = 0
while l < r:
if height[l] < height[r]:
if height[l] >= left_max:
left_max = height[l]
else:
water += left_max - height[l]
l += 1
else:
if height[r] >= right_max:
right_max = height[r]
else:
water += right_max - height[r]
r -= 1
return water
print(trap([0,1,0,2,1,0,1,3,2,1,2,1]))  # 6

import random
def find_kth_largest(nums, k):
def quick_select(l, r, k):
pivot_idx = random.randint(l, r)
nums[pivot_idx], nums[r] = nums[r], nums[pivot_idx]
pivot = nums[r]
store = l
for i in range(l, r):
if nums[i] >= pivot:
nums[store], nums[i] = nums[i], nums[store]
store += 1
nums[store], nums[r] = nums[r], nums[store]
if k == store: return nums[store]
if k < store: return quick_select(l, store-1, k)
return quick_select(store+1, r, k)
return quick_select(0, len(nums)-1, k-1)
print(find_kth_largest([3,2,1,5,6,4], 2))  # 5

def knapsack(weights, values, capacity):
n = len(weights)
dp = [[0]*(capacity+1) for _ in range(n+1)]
for i in range(1, n+1):
for w in range(capacity+1):
if weights[i-1] <= w:
dp[i][w] = max(dp[i-1][w], dp[i-1][w-weights[i-1]] + values[i-1])
else:
dp[i][w] = dp[i-1][w]
return dp[n][capacity]
print(knapsack([2, 3, 4], [3, 4, 5], 5))  # 7

